package ru.devimind.chitalka.checks;

import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.view.accessibility.*;
import android.accessibilityservice.AccessibilityServiceInfo;
import android.widget.*;
import org.json.*;
import ru.devimind.chitalka.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

/** Fixtures are isolated books; no existing heroes or notes are changed. */
public final class HeroRelationChecks extends Instrumentation {
    private Activity activity;private Library library;private File folder;private final List<String> own=new ArrayList<>();private final JSONArray checks=new JSONArray();
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    private void expect(boolean value,String text){if(!value)throw new AssertionError(text);}
    private void pass(String text){checks.put(text);Bundle result=new Bundle();result.putString("check",text);sendStatus(0,result);}
    private AccessibilityNodeInfo find(AccessibilityNodeInfo node,String value){if(node==null)return null;if(value.equalsIgnoreCase(String.valueOf(node.getText()))||value.equals(String.valueOf(node.getContentDescription()))||value.equals(node.getViewIdResourceName()))return node;if("android.webkit.WebView".contentEquals(node.getClassName()))return null;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo n=find(node.getChild(i),value);if(n!=null)return n;}return null;}
    private void tap(String text){for(int i=0;i<60;i++){AccessibilityNodeInfo node=find(getUiAutomation().getRootInActiveWindow(),text);while(node!=null&&!node.isClickable())node=node.getParent();if(node!=null&&node.performAction(AccessibilityNodeInfo.ACTION_CLICK)){SystemClock.sleep(220);return;}SystemClock.sleep(100);}throw new AssertionError("Missing control: "+text);}
    private void inputDialog(String value){AccessibilityNodeInfo node=find(getUiAutomation().getRootInActiveWindow(),"ru.devimind.chitalka:id/hero_relation_description");expect(node!=null,"Description field exists");Bundle text=new Bundle();text.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);expect(node.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,text),"Description input");SystemClock.sleep(100);}
    private String dialogText(){AccessibilityNodeInfo node=find(getUiAutomation().getRootInActiveWindow(),"ru.devimind.chitalka:id/hero_relation_description");return node==null?null:String.valueOf(node.getText());}
    private void invoke(String name,String id)throws Exception{Method method=MainActivity.class.getDeclaredMethod(name,String.class);method.setAccessible(true);runOnMainSync(()->{try{method.invoke(activity,id);}catch(Exception error){throw new RuntimeException(error);}});SystemClock.sleep(400);}
    private void shot(String name)throws Exception{SystemClock.sleep(500);Bitmap bitmap=getUiAutomation().takeScreenshot();try(OutputStream output=new FileOutputStream(new File(folder,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,output);}bitmap.recycle();}
    private Library.Note hero(String book,String name){Library.Note n=library.add(book,"hero",-1,"Описание героя "+name);n.title=name;library.save(n);return n;}
    private void invalid(Runnable action,String message){int before=library.bookHeroRelations(own.get(0)).size();boolean rejected=false;try{action.run();}catch(IllegalArgumentException error){rejected=true;}expect(rejected&&before==library.bookHeroRelations(own.get(0)).size(),message);}
    private void runChecks()throws Exception{
        expect(library.getReadableDatabase().getVersion()==5,"Current schema v5");SQLiteDatabase fresh=SQLiteDatabase.create(null);try{library.onConfigure(fresh);library.onCreate(fresh);try(Cursor c=fresh.rawQuery("SELECT COUNT(*) FROM hero_relations",null)){c.moveToFirst();expect(c.getInt(0)==0,"Fresh schema includes relations");}}finally{fresh.close();}pass("Миграция до SQLite 5 и создание новой базы с таблицей связей");
        String book=library.addPaper();own.add(book);Library.BookRow row=library.book(book);row.title="Связи героев — проверка";library.saveBook(row);Library.Note a=hero(book,"Анна"),b=hero(book,"Иван"),c=hero(book,"Мария"),thought=library.add(book,"thought",-1,"Это мысль, не герой");String otherBook=library.addPaper();own.add(otherBook);Library.Note foreign=hero(otherBook,"Герой другой книги");
        AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;getUiAutomation().setServiceInfo(info);activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));runOnMainSync(()->activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON));invoke("showBookDetails",book);tap("Начать чтение");tap("Конспект");tap("Герои");tap("Анна");tap("ru.devimind.chitalka:id/hero_relations");expect(find(getUiAutomation().getRootInActiveWindow(),"+  Связать с героем")!=null,"Empty relation screen");tap("+  Связать с героем");expect(find(getUiAutomation().getRootInActiveWindow(),"Анна")==null&&find(getUiAutomation().getRootInActiveWindow(),"Герой другой книги")==null,"Picker excludes self and other books");tap("Иван");inputDialog("Анна — сестра Ивана. Они помогают друг другу.");shot("relation-editor");tap("Сохранить");Library.HeroRelation ab=library.heroRelationBetween(a.id,b.id);expect(ab!=null&&library.heroRelations(a.id).size()==1&&library.heroRelations(b.id).size()==1,"Single shared relation");expect(ab.description.equals("Анна — сестра Ивана. Они помогают друг другу."),"Description retained");shot("relations-list");pass("Создание связи из карточки героя с описанием; одна запись доступна с обеих сторон");
        tap("Открыть героя: Иван");expect(((EditText)activity.findViewById(R.id.note_title)).getText().toString().equals("Иван"),"Counterpart card opened");tap("ru.devimind.chitalka:id/hero_relations");tap("Связь с героем: Анна");expect(dialogText().equals(ab.description),"Same description from second hero");inputDialog("Анна и Иван — родственники.\nПосле ссоры они помирились.");tap("Сохранить");expect(library.heroRelationBetween(a.id,b.id).id.equals(ab.id)&&library.heroRelation(ab.id).description.contains("помирились"),"Editing updates same row");pass("Переход в карточку второго героя и изменение общей связи с любой стороны");
        tap("+  Связать с героем");tap("Анна · связь уже есть");expect(dialogText().contains("помирились"),"Reverse duplicate opens existing description");inputDialog("Несохранённое изменение");tap("Отмена");expect(library.bookHeroRelations(book).size()==1&&!library.heroRelation(ab.id).description.contains("Несохранённое"),"Cancel leaves relation unchanged");tap("+  Связать с героем");tap("Мария");inputDialog("Отменённая новая связь");tap("Отмена");expect(library.heroRelationBetween(b.id,c.id)==null,"Canceled add creates no row");pass("Повторный выбор пары открывает существующую связь; отмена не изменяет данные");
        ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);runOnMainSync(activity::recreate);Activity restored=waitForMonitorWithTimeout(monitor,5000);removeMonitor(monitor);expect(restored!=null,"Activity recreated");activity=restored;for(int i=0;i<100&&find(getUiAutomation().getRootInActiveWindow(),"Связь с героем: Анна")==null;i++)SystemClock.sleep(100);expect(find(getUiAutomation().getRootInActiveWindow(),"Связь с героем: Анна")!=null,"Relation screen restored");pass("Сохранённая связь и экран списка восстанавливаются после пересоздания Activity");
        invalid(()->library.connectHeroes(a.id,a.id,"Сам с собой"),"Self link rejected");invalid(()->library.connectHeroes(a.id,foreign.id,"Другая книга"),"Cross-book link rejected");invalid(()->library.connectHeroes(a.id,thought.id,"Мысль"),"Only hero notes accepted");invalid(()->library.connectHeroes(b.id,a.id,"Дубликат"),"Reverse duplicate rejected by API");expect(library.heroRelation(ab.id).description.contains("помирились"),"Failed writes do not overwrite original");pass("Защита от связи с собой, героем другой книги, обычной записью и обратного дубликата");
        tap("Удалить связь с героем: Анна");tap("Отмена");expect(library.heroRelation(ab.id)!=null,"Cancel deletion");tap("Удалить связь с героем: Анна");tap("Удалить");expect(library.heroRelation(ab.id)==null&&library.heroRelations(a.id).isEmpty()&&library.note(a.id)!=null&&library.note(b.id)!=null,"Relation removed from both without removing heroes");pass("Удаление связи с подтверждением; оба героя сохраняются");
        Library.HeroRelation newAB=library.connectHeroes(a.id,b.id,"Родственники после примирения"),ac=library.connectHeroes(a.id,c.id,"");expect(library.heroRelation(ac.id).description.isEmpty(),"Description may be filled later");library.updateHeroRelation(ac.id,"Анна знает Марию с детства.\nОни помогают друг другу.");b.title="Иван Петров";library.save(b);invoke("showHeroRelations",a.id);expect(find(getUiAutomation().getRootInActiveWindow(),"Связь с героем: Иван Петров")!=null,"Renamed hero shown live");String markdown=library.markdown(book,library.load(book));expect(markdown.contains("## Связи героев")&&markdown.contains("Иван Петров")&&markdown.indexOf("Родственники после примирения")==markdown.lastIndexOf("Родственники после примирения")&&markdown.contains("Анна знает Марию с детства.\nОни помогают друг другу."),"Export uses current names, full text and one shared relation");pass("Переименование героя обновляет подписи; Markdown сохраняет связи и многострочное описание без дубликатов");
        library.delete(b);expect(library.heroRelation(newAB.id)==null&&library.heroRelation(ac.id)!=null&&library.note(a.id)!=null&&library.note(c.id)!=null,"Hero deletion removes only its links");library.deleteBook(book,false);expect(library.book(book).archived&&library.heroRelation(ac.id)!=null&&library.markdown(book,library.load(book)).contains("Связи героев"),"Notebook retention includes relations");invoke("showBookDetails",book);for(int i=0;i<80&&find(getUiAutomation().getRootInActiveWindow(),"Герои")==null;i++)SystemClock.sleep(100);tap("Герои");tap("Анна");tap("ru.devimind.chitalka:id/hero_relations");expect(find(getUiAutomation().getRootInActiveWindow(),"Связь с героем: Мария")!=null,"Retained notebook relation UI");shot("saved-notebook-relations");library.deleteBook(book,true);expect(library.heroRelation(ac.id)==null&&library.note(a.id)==null&&library.note(c.id)==null,"Whole notebook cascades relationships");try(Cursor cursor=library.getReadableDatabase().rawQuery("PRAGMA foreign_key_check",null)){expect(!cursor.moveToFirst(),"Foreign keys intact");}pass("Удаление героя и книги: каскад связей, сохранение конспекта со связями и целостность базы");
    }
    @Override public void onStart(){Bundle result=new Bundle();JSONObject report=new JSONObject();try{library=new Library(getTargetContext());folder=new File(getTargetContext().getFilesDir(),"hero-relations-0.1.11");folder.mkdirs();runChecks();report.put("result","PASS");result.putString("result","PASS: "+checks.length()+" groups");}catch(Throwable error){try{report.put("result","FAIL").put("error",error.toString());}catch(Exception ignored){}result.putString("result","FAIL: "+error);}
        finally{if(activity!=null)runOnMainSync(activity::finish);for(String id:own)try{library.deleteBook(id,true);}catch(Exception ignored){}}
        try{report.put("checks",checks);try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(folder,"checks.json")),"UTF-8")){out.write(report.toString(2));}}catch(Exception ignored){}
        finish("PASS".equals(report.optString("result"))?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
